#include "MindRuntime.hpp"
namespace elysium::citizens {double MindRuntime::clamp01(double v){return std::clamp(std::isfinite(v)?v:0.0,0.0,1.0);}bool MindRuntime::add(MindState m,std::string&w){if(!m.citizen){w="invalid mind";return false;}for(auto&n:m.needs){n.deficit=clamp01(n.deficit);n.decayPerTick=std::max(0.0,std::isfinite(n.decayPerTick)?n.decayPerTick:0.0);}if(!rows_.emplace(m.citizen,std::move(m)).second){w="duplicate mind";return false;}return true;}void MindRuntime::advance(StableId id,std::uint64_t ticks){auto i=rows_.find(id);if(i==rows_.end())return;auto&m=i->second;double deficit=0;for(auto&n:m.needs){n.deficit=clamp01(n.deficit+n.decayPerTick*double(ticks));deficit+=n.deficit;}double mem=0;for(auto&x:m.memories)mem+=x.intensity*x.valence;double traitStress=1.0;for(auto&t:m.traits)traitStress+=std::clamp(-t.weight,0.0,1.0)*0.1;m.stress=std::clamp((deficit*0.12-mem*0.03)*traitStress,0.0,1.0);m.focus=std::clamp(1.0-m.stress*0.7,0.1,1.25);m.stressBand=m.stress>=.85?3:m.stress>=.6?2:m.stress>=.3?1:0;}bool MindRuntime::satisfy(StableId id,ContentId n,double amount){auto i=rows_.find(id);if(i==rows_.end())return false;for(auto&x:i->second.needs)if(x.id==n){x.deficit=clamp01(x.deficit-std::max(0.0,amount));return true;}return false;}MindSnapshot MindRuntime::snapshot(StableId id)const{MindSnapshot s{};auto i=rows_.find(id);if(i==rows_.end())return s;s.focus=i->second.focus;s.stress=i->second.stress;s.stressBand=i->second.stressBand;for(auto&n:i->second.needs)s.needDeficits.push_back({n.id,n.deficit});return s;}bool MindRuntime::shouldCrisis(StableId id,std::uint64_t tick,double threshold)const{auto i=rows_.find(id);return i!=rows_.end()&&tick>=i->second.crisisCooldownUntil&&i->second.stress>=clamp01(threshold);}}
